    // [WSCoop] Skill XP shared by a nearby coven member (never re-shared).
    void WSGrantSharedXP(FGameplayTag SkillTag, float XP)
    {
        if (!System::IsServer() || XP <= 0)
            return;

        for (int TaskID = 0; TaskID < ProgressionData.Num(); TaskID++)
        {
            if (ProgressionData[TaskID].PlayerSkillTag != SkillTag)
                continue;

            FPlayerSkillProgress& SkillProgress = ProgressionData[TaskID];
            if (SkillProgress.Level >= MaxLevel)
                return;

            const int PreviousLevel = SkillProgress.Level;
            const float PreviousPercent = SkillProgress.GetSkillPercent(SkillTemplates.LevelScalingFactor);
            SkillProgress.AddXP(XP, SkillTemplates.LevelScalingFactor, MaxLevel);
            const int NewLevel = SkillProgress.Level;

            if (NewLevel > PreviousLevel)
                OnSkillLeveledUp(SkillProgress.PlayerSkillTag, PreviousLevel, NewLevel);
            if (NewLevel >= MaxLevel)
            {
                OnMaxLevelReached(SkillProgress.PlayerSkillTag, TaskID);
                return;
            }

            const float UpdatedPercent = SkillProgress.GetSkillPercent(SkillTemplates.LevelScalingFactor);
            if (Game::GetLocalPlayer() == Owner)
                OnSkillUpdated.Broadcast(SkillProgress.PlayerSkillTag, SkillProgress, SkillTemplates, PreviousPercent, UpdatedPercent);
            else
                OnSkillUpdated_Client(SkillProgress, PreviousPercent, UpdatedPercent);
            return;
        }
